#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
​
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
​
    int m, n;
    cin >> n >> m;
​
    vector<int> order(m);
    for (int i = 0; i < m; i++) cin >> order[i];
​
    vector<vector<int>> goods(n, vector<int>(m));
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            cin >> goods[i][j];
​
    // 按照题目要求自定义排序        
    sort(goods.begin(), goods.end(), [&](const vector<int>& a, const vector<int>& b) {
        for (int i = 0; i < m; i++) {
            if (a[i] == b[i]) continue;
            if (order[i] == 1)  // 降序
                return a[i] > b[i];
            else                 // 升序
                return a[i] < b[i];
        }
        return false; // 全部相等
    });
    // 输出结果
    for (auto& item : goods) {
        for (int j = 0; j < m; j++) {
            if (j) cout << " ";
            cout << item[j];
        }
        cout << "\n";
    }
​
    return 0;
}
