public class Main {
    public static void main(String[] args) throws IOException {
        // 高效输入
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken()); // 商品数量
        int m = Integer.parseInt(st.nextToken()); // 属性数量
​
        st = new StringTokenizer(br.readLine());
        int[] order = new int[m];
        for (int i = 0; i < m; i++) order[i] = Integer.parseInt(st.nextToken());
​
        int[][] goods = new int[n][m];
        for (int i = 0; i < n; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 0; j < m; j++) {
                goods[i][j] = Integer.parseInt(st.nextToken());
            }
        }
​
        // 按照题目要求自定义排序
        Arrays.sort(goods, (a, b) -> {
            for (int i = 0; i < m; i++) {
                if (a[i] == b[i]) continue;
                if (order[i] == 1)  // 降序
                    return b[i] - a[i];
                else                 // 升序
                    return a[i] - b[i];
            }
            return 0; // 全部相等
        });
​
        // 使用stringbuilder优化
        StringBuilder sb = new StringBuilder();
        for (int[] item : goods) {
            for (int j = 0; j < m; j++) {
                if (j > 0) sb.append(' ');
                sb.append(item[j]);
            }
            sb.append('\n');
        }
        System.out.print(sb);
    }
}
