// 使用 readline 接口流式读取输入
const readline = require('readline');
​
const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});
​
let input = [];
rl.on('line', (line) => {
  if (line.trim().length > 0) input.push(line.trim());
});
​
rl.on('close', () => {
  // 第一行: n m
  const [n, m] = input[0].split(' ').map(Number);
​
  // 第二行: 排序规则
  const order = input[1].split(' ').map(Number);
​
  // 接下来 n 行: 每个商品的 m 个属性
  const goods = [];
  for (let i = 0; i < n; i++) {
    goods.push(input[2 + i].split(' ').map(Number));
  }
​
  // 自定义排序
  goods.sort((a, b) => {
    for (let i = 0; i < m; i++) {
      if (a[i] === b[i]) continue;
      if (order[i] === 1) return b[i] - a[i]; // 降序
      else return a[i] - b[i];                // 升序
    }
    return 0; // 全部相等
  });
​
  // 输出结果
  let output = goods.map(row => row.join(' ')).join('\n');
  console.log(output);
});
