package main
​
import (
    "bufio"
    "fmt"
    "os"
    "sort"
)
​
func main() {
    in := bufio.NewReader(os.Stdin)
​
    var n, m int
    fmt.Fscan(in, &n, &m)
​
    order := make([]int, m)
    for i := 0; i < m; i++ {
        fmt.Fscan(in, &order[i])
    }
​
    goods := make([][]int, n)
    for i := 0; i < n; i++ {
        goods[i] = make([]int, m)
        for j := 0; j < m; j++ {
            fmt.Fscan(in, &goods[i][j])
        }
    }
​
    // 自定义排序
    sort.Slice(goods, func(i, j int) bool {
        a, b := goods[i], goods[j]
        for k := 0; k < m; k++ {
            if a[k] == b[k] {
                continue
            }
            if order[k] == 1 { // 降序
                return a[k] > b[k]
            } else { // 升序
                return a[k] < b[k]
            }
        }
        return false // 全部相等
    })
​
    // 输出结果
    out := bufio.NewWriter(os.Stdout)
    defer out.Flush()
    for _, item := range goods {
        for j := 0; j < m; j++ {
            if j > 0 {
                fmt.Fprint(out, " ")
            }
            fmt.Fprint(out, item[j])
        }
        fmt.Fprintln(out)
    }
}
